tot = sum(loved.values()) or 1
print("\ntop tags among 4-5 star fiction:", [t for t, _ in loved.most_common(12)])
C = sum(b["rating"] or 0 for b in d["cand"] if b["rating"]) / max(1, sum(1 for b in d["cand"] if b["rating"]))
